//! `ogar_codebook` — the OGAR concept codebook, wire-compatible mirror (D-OVC-1).
//!
//! OGAR's `ogar-vocab` crate owns the canonical class-identity codebook: a curated
//! `(concept, u16)` table whose ids are **domain-encoded** as `0xDDCC` (`DD` = the
//! domain high byte, `CC` = the concept slot, `CC == 0x00` = the domain root,
//! reserved). Its own doc-comment says the long-term home of these types is
//! `lance-graph-contract`, "alongside `ClassId` and the `NodeGuid` LE layout."
//!
//! This module is that home — but **wire-compatible, not a dependency**. The
//! contract is zero-runtime-dep by design, so it does NOT depend on `ogar-vocab`;
//! instead both crates agree on the **wire**: a concept's id is one `u16`,
//! serialized little-endian, and that id IS the low 16 bits of
//! [`NodeGuid::classid`](crate::NodeGuid). Any encoder/decoder that agrees on
//! `u16` LE is compatible regardless of which crate it links. The parity tests
//! below pin the shared values; if OGAR's `CODEBOOK` ever moves an id, BOTH sides
//! must update together (the drift guard).
//!
//! What this mirror carries: the **codebook-id layer** the contract needs to route
//! a `classid` to its domain ([`canonical_concept_domain`], [`classid_concept_domain`])
//! and to resolve a canonical-concept string to its id ([`canonical_concept_id`],
//! [`LabelDTO::from_canonical`]). It also carries the **APP / render-prefix
//! layer** (the hi u16): [`AppPrefix`] (the §2 allocation table as typed data),
//! [`render_classid`] / [`render_classid_for_concept`] (compose), and
//! [`classid_app_prefix`] / [`classid_concept`] (decompose) — the membrane
//! equivalent of OGAR `render_classid_for::<P>()`, so a zero-dep consumer stamps
//! the prefix from ONE source instead of hardcoding `0x000N`. What it does NOT carry: OGAR's curator-alias
//! normalizer (`canonical_concept` — the large `"Issue"`/`"WorkPackage"` →
//! `"project_work_item"` table). Alias normalization stays in `ogar-vocab`; this
//! module resolves canonical-shaped concept strings only (hence `from_canonical`,
//! not `from_alias` — naming the difference rather than faking parity).
//!
//! Cross-ref: `.claude/plans/ogar-vocab-contract-codebook-migration-v1.md`,
//! OGAR `crates/ogar-vocab/src/lib.rs` (`CODEBOOK` / `ConceptDomain` / `LabelDTO`),
//! [`canonical_node`](crate::canonical_node) (`CLASSID_*`), [`codebook`](crate::codebook)
//! (the FINER per-family scope — this is the coarse concept/classid scope).

/// Codebook **domain** — the high byte of a canonical id (`id >> 8`, the `0xDDCC`
/// layout). Lets a consumer route on domain in O(1) from just the `u16`, no table
/// lookup. Reserved high-byte slots have a stable variant even before a concept
/// lands there, so consumers can branch on them today. Mirrors OGAR
/// `ogar_vocab::ConceptDomain` (wire-compatible — same `id >> 8` discriminant).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum ConceptDomain {
    /// `0x00XX` — reserved (`0x0000` is [`NodeGuid::CLASSID_DEFAULT`]).
    Reserved,
    /// `0x01XX` — project-management (OpenProject ↔ Redmine).
    ProjectMgmt,
    /// `0x02XX` — commerce / billing / ERP (Odoo ↔ OSB).
    Commerce,
    /// `0x03XX` — Ontology (OBO reference vocabulary; plug-and-play, never
    /// pulled into ERP consumers). Mirrors OGAR
    /// `ogar_vocab::ConceptDomain::Ontology`.
    Ontology,
    /// `0x04XX` — Weather / Atmosphere. Shared forecast and atmospheric cells.
    Weather,
    /// `0x07XX` — OSINT (open-source intelligence / Palantir-Gotham).
    Osint,
    /// `0x08XX` — OCR (optical character recognition / document extraction).
    Ocr,
    /// `0x09XX` — Health (clinical / patient / care).
    Health,
    /// `0x0AXX` — Anatomy (FMA reference ontology; bones / skeleton / joints).
    /// Public structural reference, distinct from `Health` PHI — the FMA
    /// anatomy domain (`anatomical_structure` / `skeleton` / `bone` / `joint`).
    Anatomy,
    /// `0x0BXX` — Auth (identity / authz: AuthStore, Zitadel, Zanzibar, Ory Keto).
    Auth,
    /// `0x0CXX` — Automation (the HIRO IT-automation stack: the MARS structural
    /// CMDB — `mars_application` / `mars_resource` / `mars_software` /
    /// `mars_machine` — and the Automation DO-arm actuators — `knowledge_item` /
    /// `mars_node_template` / `action_handler` / `action_applicability` /
    /// `automation_trigger`). Infrastructure config, not PHI. Mirrors OGAR
    /// `ogar_vocab::ConceptDomain::Automation`.
    Automation,
    /// `0x0DXX` — HR (employment / org / contracts; `vcard:Individual` /
    /// `org:OrganizationalUnit` / `org:Role` / `fibo:Contract` alignment).
    /// Public master-data for person + organizational-unit + role +
    /// employment-contract entities; distinct from `Auth` (the IdP→classid
    /// bridge) and from `Health` PHI. Mirrors OGAR
    /// `ogar_vocab::ConceptDomain::HR` (added in OGAR PR #127).
    HR,
    /// `0x0EXX` — Genetics (pharmacogenomics; CPIC gene–drug guidelines, variant
    /// annotations). Public reference knowledge, distinct from `Health` PHI.
    /// Operator-allocated 2026-06-26 (`0x0D` was already HR). Mirror target
    /// `ogar_vocab::ConceptDomain::Genetics` — OGAR catches up under the drift
    /// guard (the parity tests pin `0x0E00 → Genetics`).
    Genetics,
    /// `0x0FXX` — Geo (OpenStreetMap geodata: node / way / relation / changeset /
    /// element-tag / member / note / GPX trace / user). Public spatial reference
    /// data; the Geo domain binds the HHTL tier axes to literal (x, y) tiles
    /// (OGAR canon "256×256 centroid tile", D-BOTHCASC). Mirrors OGAR
    /// `ogar_vocab::ConceptDomain::Geo`; the parity tests pin `0x0F00 → Geo`.
    Geo,
    /// `0x17XX` — Blocks (the `ogar-loco` low-code substrate's domain: the
    /// shared block/call opcode vocabulary; `0x1701`/`0x1702` are loco's node
    /// shapes, `0x1717`+ per-frontend palettes). Mirrors OGAR
    /// `ogar_vocab::ConceptDomain::Blocks` (reserved 2026-08-04).
    Blocks,
    /// `0xC0XX` — Java runtime (**Panama FFM alone** — downcalls, segments,
    /// lanes, arenas, masks; the managed-runtime membrane over the SoA
    /// substrate, the FLOOR of the C-band). Valhalla deliberately has no
    /// domain slot: it is integrated as a *property* of the C0 vocabulary
    /// (`value record`-ready descriptor types), never an addressable crossing
    /// concept — canonical text in OGAR's `JavaRuntime` doc comment
    /// (PR #276 + #277). Mirrors `ogar_vocab::ConceptDomain::JavaRuntime`.
    JavaRuntime,
    /// `0xC1XX` — Analytics (the analyst estate: addressable tabular units +
    /// catalog ontology; one shared vocabulary under per-app render
    /// prefixes). Mirrors `ogar_vocab::ConceptDomain::Analytics`.
    Analytics,
    /// `0xC4XX` — Binary lifting (normalized machine-code IR + artifact
    /// ontology; Ghidra and r2sleigh are two consumers of one SLEIGH-derived
    /// vocabulary; the R2IL container concepts mint here in the ruff PR3
    /// arc, replacing `PROVISIONAL_R2IL_VARNODE = 0x0000`). Mirrors
    /// `ogar_vocab::ConceptDomain::BinaryLifting`.
    BinaryLifting,
    /// Any high-byte slot not yet assigned a domain (`0x05XX`–`0x06XX`,
    /// `0x10XX`–`0x16XX`, `0x18XX`–`0xBFXX`, `0xC2XX`–`0xC3XX` — a
    /// DELIBERATE gap, pinned like OGAR's own `0x10`–`0x16` — and
    /// `0xC5XX`+).
    Unassigned,
}

/// Resolve a canonical id's [`ConceptDomain`] from its high byte. Pure,
/// deterministic, O(1) — no table lookup. The single rule both the contract's
/// `classid → ReadMode` registry and OGAR's promotion gate route on.
#[inline]
#[must_use]
pub fn canonical_concept_domain(id: u16) -> ConceptDomain {
    match id >> 8 {
        0x00 => ConceptDomain::Reserved,
        0x01 => ConceptDomain::ProjectMgmt,
        0x02 => ConceptDomain::Commerce,
        0x03 => ConceptDomain::Ontology,
        0x04 => ConceptDomain::Weather,
        0x07 => ConceptDomain::Osint,
        0x08 => ConceptDomain::Ocr,
        0x09 => ConceptDomain::Health,
        0x0A => ConceptDomain::Anatomy,
        0x0B => ConceptDomain::Auth,
        0x0C => ConceptDomain::Automation,
        0x0D => ConceptDomain::HR,
        0x0E => ConceptDomain::Genetics,
        0x0F => ConceptDomain::Geo,
        0x17 => ConceptDomain::Blocks,
        0xC0 => ConceptDomain::JavaRuntime,
        0xC1 => ConceptDomain::Analytics,
        0xC4 => ConceptDomain::BinaryLifting,
        _ => ConceptDomain::Unassigned,
    }
}

/// Resolve a [`NodeGuid`](crate::NodeGuid) `classid` to its [`ConceptDomain`] (D-OVC-4). The
/// codebook id is the CANON half of the classid (under the active
/// [`CLASSID_ORDER`] — the HIGH u16 since the P1 flip); the other half is the
/// custom/render prefix. So a domain route is
/// `canonical_concept_domain(classid_canon(classid))`. This is the coarse sibling of the
/// per-family scope in [`codebook`](crate::codebook): classid (domain) selects the
/// coarse codebook; `family` selects the sub-codebook (longest-prefix-wins).

1	//! PROBE-R2IL-SLAG-BOUNDARY-1 — the HONEST BOUNDARY of the R2IL pass-1 seven-
2	//! opcode furnace convention: what it could NOT classify, and whether that
3	//! residual is a small set of named, bounded reasons (legitimate slag) or a
4	//! diffuse, unbounded catch-all (a sign the convention itself is wrong).
5	//!
6	//! # What the data is
7	//!
8	//! `probe_r2il_real_episodes.rs` (sibling probe, read in full before writing
9	//! this one) measures the INSIDE of the ruff-side R2IL pass-1 convention — the
10	//! classified `FlatFact` rows. This probe measures the OUTSIDE: the furnace's
11	//! own `ResidualLedger` — every fact the seven-opcode convention could not
12	//! carry, recorded under an explicit, non-empty reason (never silently
13	//! dropped, never a catch-all "other"). Two env-gated artifacts, neither
14	//! fabricated:
15	//!
16	//! - `R2IL_SLAG_TSV` — the slag ledger, two sections keyed by column 0:
17	//!   `grouped` (from `ResidualLedger::grouped()`): 5 columns — `section
18	//!   shape_id reason count example_facet`. `by_address` (from
19	//!   `ResidualLedger::by_address()`, the proposer's work queue): **4
20	//!   columns**, NOT 5 — `section prefix shape_id count`. No `reason` column on
21	//!   that side; a `by_address` row's reason is only recoverable by joining its
22	//!   `shape_id` back into `grouped`.
23	//!
24	//!   **Schema-drift note (found by reading the real file, not assumed):** the
25	//!   brief for this probe described both sections as 5-column with a `reason`
26	//!   field. The file's own header lines (`#schema section shape_id reason
27	//!   count example_facet` vs `#schema section prefix shape_id count`) say
28	//!   otherwise; this probe parses what the file actually declares. S1 encodes
29	//!   this as the per-section column arity.
30	//!
31	//! - `R2IL_ORE_TSV` — the classified-rows TSV (same file
32	//!   `probe_r2il_real_episodes` reads): 13 tab-separated columns. Used ONLY
33	//!   for the classified-vs-residual ratio (S5); if absent, S5 is skipped
34	//!   rather than inventing a classified-row count.
35	//!
36	//! Provenance: ruff-side R2IL pass-1 harvest over 143 real functions from 2
37	//! real x86-64 ELF64 binaries (`r2sleigh/tests/e2e/{stress_test,stress_test_opt}`),
38	//! `AdaWorldAPI/ruff`, `crates/ruff_r2il/examples/harvest_r2il.rs`. The slag
39	//! ledger is `ruff_r2il::furnace::ResidualLedger`'s committed output; this
40	//! probe reads that evidence, it does not regenerate it.
41	//!
42	//! Facts cited from the brief as already independently measured on the real
43	//! artifact (cited here, NOT asserted as hardcoded literals — every number
44	//! this probe gates on is recomputed at runtime from whatever file the env
45	//! var names): 489 total lines, 43 `grouped` rows, 440 `by_address` rows;
46	//! grouped reasons `opcode_not_in_convention` (39 rows), `variadic_arity` (2),
47	//! `no_facet_coordinate` (1), `memory_object_escaped` (1).
48	//!
49	//! ```sh
50	//! R2IL_SLAG_TSV=/path/to/r2il-pass1-slag.tsv \
51	//! R2IL_ORE_TSV=/path/to/r2il-pass1.ore.tsv \
52	//!   cargo run -p lance-graph-planner --example probe_r2il_slag_boundary
53	//! ```
54	//!
55	//! # Pre-registrations (direction chosen BEFORE the gate computes the number;
56	//! a refutation is recorded, not adjusted away)
57	//!
58	//! - **PR-1 (S3):** the pass-1 convention is narrow (7 opcodes) by deliberate
59	//!   design, so the residual is predicted to be DOMINATED by one named reason
60	//!   (`opcode_not_in_convention`) rather than diffuse. Gate: the largest
61	//!   reason's share of total residual count exceeds one half.
62	//! - **PR-2 (S1/S4):** the furnace's own "never a silent catch-all" invariant
63	//!   holds from the OUTSIDE too — every residual row resolves to a non-empty
64	//!   named reason, and a malformed/orphaned row is a hard failure, never a
65	//!   silent skip.
66	//!
67	//! # Gates (each can fail; each failure would be a finding)
68	//!
69	//! - **S1 PARSE + CONSERVATION** — strict per-section column arity (5 for
70	//!   `grouped`, 4 for `by_address`; an unknown section or wrong arity is
71	//!   proven to panic via an embedded synthetic bad line); cross-section
72	//!   conservation — every `by_address` shape_id's summed count must equal
73	//!   EXACTLY its `grouped` count (a real join invariant: same mass, split by
74	//!   address prefix, not a tautology).
75	//! - **S2 REASON CENSUS** — per-reason row count + count-sum over `grouped`
76	//!   (the only section carrying `reason` directly). Reason set non-empty, no
77	//!   reason string empty.
78	//! - **S3 CONCENTRATION** — PR-1, with margin (share > 0.5, an actual
79	//!   majority) so a genuinely diffuse residual would refute it.
80	//! - **S4 NAMED-NOT-DROPPED** — PR-2 from the `by_address` side via join into
81	//!   `grouped`. Can-fire demonstrated with a synthetic orphan shape_id (not in
82	//!   the real corpus) whose join lookup must panic.
83	//! - **S5 RATIO (skippable)** — if `R2IL_ORE_TSV` set: classified rows (light
84	//!   13-column check) vs S1's residual total; prints both + ratio; asserts
85	//!   only nonzero — no direction pre-registered, none was measured ahead of
86	//!   time. Unset → `SKIPPED`, never fabricated.
87	//! - **S6 FENCE** — not a re-ingest path into ruff; slag is pass-1
88	//!   SEVEN-OPCODE-CONVENTION slag, not "everything x86-64 can do"; corpus is 2
89	//!   binaries from one source, not a representative sample.
90	//!
91	//! # Fences
92	//!
93	//! - No import of `ruff_r2il` (separate workspace) — schema cited from the
94	//!   file's own header, verified against the real file.
95	//! - No mint: no classid, no vocabulary table, no BPE, no learner subsystem.
96	//! - No performance claims. Counts, sums, and ratios only.
97	
98	use std::collections::BTreeMap;
99	use std::process::ExitCode;
100	
101	// ================================================================================================
102	// Slag TSV reading (probe-local; strict — an unknown section or bad arity panics)
103	// ================================================================================================
104	
105	#[derive(Clone)]
106	struct GroupedRow {
107	    reason: String,
108	    count: u64,
109	    #[allow(dead_code)] // read for schema completeness; not needed by any gate below
110	    example_facet: String,
111	}
112	
113	struct ByAddressRow {
114	    #[allow(dead_code)] // read for schema completeness; not needed by any gate below
115	    prefix: String,
116	    shape_id: String,
117	    count: u64,
118	}
119	
120	enum ParsedLine {
121	    Grouped(String, GroupedRow), // (shape_id, row)
122	    ByAddress(ByAddressRow),
123	}
124	
125	/// Parses one non-comment slag line. PANICS (does not silently skip) on an
126	/// unknown section name or a wrong column count for the section it declares —
127	/// this is the "parse strictly" half of S1/S2, and S1 proves it by construction
128	/// with a synthetic bad line below.
129	fn parse_slag_line(line: &str) -> ParsedLine {
130	    let f: Vec<&str> = line.split('\t').collect();
131	    match f.first().copied() {
132	        Some("grouped") => {
133	            assert!(
134	                f.len() == 5,
135	                "grouped row must have exactly 5 columns, got {} ({line:?})",
136	                f.len()
137	            );
138	            let shape_id = f[1].to_string();
139	            let reason = f[2].to_string();
140	            let count: u64 = f[3].parse().expect("grouped count must be u64");
141	            let example_facet = f[4].to_string();
142	            ParsedLine::Grouped(
143	                shape_id,
144	                GroupedRow {
145	                    reason,
146	                    count,
147	                    example_facet,
148	                },
149	            )
150	        }
151	        Some("by_address") => {
152	            assert!(
153	                f.len() == 4,
154	                "by_address row must have exactly 4 columns, got {} ({line:?})",
155	                f.len()
156	            );
157	            let prefix = f[1].to_string();
158	            let shape_id = f[2].to_string();
159	            let count: u64 = f[3].parse().expect("by_address count must be u64");
160	            ParsedLine::ByAddress(ByAddressRow {
161	                prefix,
162	                shape_id,
163	                count,
164	            })
165	        }
166	        other => {
167	            panic!("unknown slag section {other:?} in line {line:?} — refusing to silently skip")
168	        }
169	    }
170	}
171	
172	fn parse_slag(tsv: &str) -> (BTreeMap<String, GroupedRow>, Vec<ByAddressRow>) {
173	    let mut grouped: BTreeMap<String, GroupedRow> = BTreeMap::new();
174	    let mut by_address: Vec<ByAddressRow> = Vec::new();
175	    for line in tsv.lines() {
176	        if line.starts_with('#') || line.is_empty() {
177	            continue;
178	        }
179	        match parse_slag_line(line) {
180	            ParsedLine::Grouped(shape_id, row) => {
181	                assert!(
182	                    grouped.insert(shape_id.clone(), row).is_none(),
183	                    "duplicate grouped shape_id {shape_id} — furnace's grouped() should be unique per shape"
184	                );
185	            }
186	            ParsedLine::ByAddress(row) => by_address.push(row),
187	        }
188	    }
189	    (grouped, by_address)
190	}
191	
192	/// Runs `f` with the default panic hook silenced, returning whether it panicked.
193	/// Used to demonstrate (not merely assert) that strict parsing / strict joining
194	/// actually rejects bad input, without polluting stderr with the expected panic.
195	fn panics_silently<F: FnOnce() + std::panic::UnwindSafe>(f: F) -> bool {
196	    let prev_hook = std::panic::take_hook();
197	    std::panic::set_hook(Box::new(|_| {}));
198	    let result = std::panic::catch_unwind(f);
199	    std::panic::set_hook(prev_hook);
200	    result.is_err()
201	}
202	
203	// ================================================================================================
204	// main
205	// ================================================================================================
206	
207	/// The by_address -> grouped reason join, in ONE place.
208	///
209	/// META-REVIEW FIX (P0): S4's loop and S4's can-fire both call this, so the can-fire
210	/// exercises the real code path rather than a re-typed copy of it. Panicking here (rather
211	/// than returning Option) is deliberate: an orphaned residual row means the ledger lost a
212	/// name, which is exactly the "no catch-all, nothing dropped" invariant S4 exists to check.
213	fn reason_for<'a>(grouped: &'a BTreeMap<String, GroupedRow>, shape_id: &str) -> &'a str {
214	    match grouped.get(shape_id) {
215	        Some(g) => g.reason.as_str(),
216	        None => panic!("by_address row's shape_id {shape_id} has no reason to join"),
217	    }
218	}
219	
220	fn main() -> ExitCode {
221	    let Some(slag_path) = std::env::var_os("R2IL_SLAG_TSV") else {
222	        eprintln!(
223	            "CORPUS ABSENT — this probe measures only the real slag ledger and never fabricates."
224	        );
225	        eprintln!("Fetch the real R2IL pass-1 slag ledger (ruff_r2il::furnace committed harvest artifacts)");
226	        eprintln!("and re-run:");
227	        eprintln!(
228	            "  R2IL_SLAG_TSV=/path/to/r2il-pass1-slag.tsv [R2IL_ORE_TSV=/path/to/r2il-pass1.ore.tsv] \\"
229	        );
230	        eprintln!("    cargo run -p lance-graph-planner --example probe_r2il_slag_boundary");
231	        return ExitCode::from(2);
232	    };
233	    let Ok(slag_tsv) = std::fs::read_to_string(&slag_path) else {
234	        eprintln!("CORPUS ABSENT — R2IL_SLAG_TSV={slag_path:?} is not readable. Never fabricated.");
235	        return ExitCode::from(2);
236	    };
237	
238	    let (grouped, by_address) = parse_slag(&slag_tsv);
239	    let mut pass = 0u32;
240	    let mut total_gates = 0u32;
241	
242	    // -------------------------------------------------------------------------------------------
243	    // S1 PARSE + CONSERVATION
244	    // -------------------------------------------------------------------------------------------
245	    let conservation_total: u64 = {
246	        total_gates += 1;
247	
248	        // Can-fire: an unknown section name must be a hard failure, not a silent skip.
249	        let unknown_section_panics = panics_silently(|| {
250	            let _ = parse_slag_line("bogus\tfoo\tbar\tbaz");
251	        });
252	        assert!(
253	            unknown_section_panics,
254	            "an unknown slag section must panic — strict parsing is required, not silent skip"
255	        );
256	
257	        // Can-fire: a `grouped` row with the wrong column count must also be a hard failure.
258	        let bad_arity_panics = panics_silently(|| {
259	            let _ = parse_slag_line("grouped\tshapeid_only_four_cols\treason\t5");
260	        });
261	        assert!(
262	            bad_arity_panics,
263	            "a grouped row with wrong column arity must panic, not silently misparse"
264	        );
265	
266	        // Cross-section conservation: sum the by_address counts per shape_id and
267	        // require EXACT equality with that shape_id's grouped count. Every
268	        // by_address shape_id must also be a member of grouped (no orphans yet —
269	        // S4 checks the orphan case with a synthetic shape_id instead of assuming
270	        // the real corpus has none).
271	        let mut by_shape_sum: BTreeMap<&str, u64> = BTreeMap::new();
272	        for row in &by_address {
273	            *by_shape_sum.entry(row.shape_id.as_str()).or_default() += row.count;
274	        }
275	        for (shape_id, summed) in &by_shape_sum {
276	            let g = grouped.get(*shape_id).unwrap_or_else(|| {
277	                panic!("by_address shape_id {shape_id} has no grouped counterpart")
278	            });
279	            assert_eq!(
280	                *summed, g.count,
281	                "conservation violated for shape_id {shape_id}: by_address sums to {summed}, grouped says {}",
282	                g.count
283	            );
284	        }
285	
286	        let total: u64 = grouped.values().map(|r| r.count).sum();
287	        pass += 1;
288	        println!(
289	            "S1 PASS  grouped_rows={} by_address_rows={} distinct_shapes_in_by_address={} \
290	             conservation: every by_address shape sums EXACTLY to its grouped count; \
291	             strict-parse can-fire proven (unknown section + bad arity both panic); total_count={total}",
292	            grouped.len(),
293	            by_address.len(),
294	            by_shape_sum.len()
295	        );
296	        total
297	    };
298	
299	    // -------------------------------------------------------------------------------------------
300	    // S2 REASON CENSUS (grouped section only — the only section carrying `reason` directly)
301	    // -------------------------------------------------------------------------------------------
302	    {
303	        total_gates += 1;
304	        let mut rows_by_reason: BTreeMap<&str, u32> = BTreeMap::new();
305	        let mut count_by_reason: BTreeMap<&str, u64> = BTreeMap::new();
306	        for row in grouped.values() {
307	            assert!(
308	                !row.reason.is_empty(),
309	                "grouped row carries an empty reason string"
310	            );
311	            *rows_by_reason.entry(row.reason.as_str()).or_default() += 1;
312	            *count_by_reason.entry(row.reason.as_str()).or_default() += row.count;
313	        }
314	        assert!(
315	            !rows_by_reason.is_empty(),
316	            "the reason census must be non-empty — a zero-reason slag ledger is unfalsifiable"
317	        );
318	        pass += 1;
319	        println!(
320	            "S2 PASS  reason census (rows, summed count) over {} grouped shapes:",
321	            grouped.len()
322	        );
323	        for (reason, rows) in &rows_by_reason {
324	            println!(
325	                "         {reason:<24} rows={rows:>3} count={:>7}",
326	                count_by_reason[reason]
327	            );
328	        }
329	    }
