331	    // -------------------------------------------------------------------------------------------
332	    // S3 CONCENTRATION — PR-1: the residual is dominated by one named reason, not diffuse.
333	    // -------------------------------------------------------------------------------------------
334	    {
335	        total_gates += 1;
336	        let mut count_by_reason: BTreeMap<&str, u64> = BTreeMap::new();
337	        for row in grouped.values() {
338	            *count_by_reason.entry(row.reason.as_str()).or_default() += row.count;
339	        }
340	        let total: u64 = count_by_reason.values().sum();
341	        let (top_reason, top_count) = count_by_reason
342	            .iter()
343	            .max_by_key(|(_, n)| **n)
344	            .expect("S2 already asserted non-empty reason census");
345	        let share = *top_count as f64 / total as f64;
346	        // PR-1, recorded not adjusted: if the residual turned out diffuse (no
347	        // reason clears a bare majority), this assertion fails and that IS the
348	        // finding — the convention would be mis-scoped, not merely under-tested.
349	        assert!(
350	            share > 0.5,
351	            "PR-1 REFUTED: no single named reason holds a majority of residual count \
352	             (top is {top_reason} at {share:.3}) — the residual reads as diffuse, not \
353	             convention-bounded"
354	        );
355	        pass += 1;
356	        println!(
357	            "S3 PASS  PR-1 holds: largest reason '{top_reason}' carries {top_count}/{total} = {share:.3} \
358	             of residual count (> 0.5 majority) — the residual is convention-bounded, not diffuse"
359	        );
360	    }
361	
362	    // -------------------------------------------------------------------------------------------
363	    // S4 NAMED-NOT-DROPPED — PR-2 from the by_address side (join back into grouped for `reason`).
364	    // -------------------------------------------------------------------------------------------
365	    {
366	        total_gates += 1;
367	        // META-REVIEW FIX (P0): this gate previously re-asserted two properties S1 and S2
368	        // had already established (S1 panics on a missing counterpart; S2 rejects an empty
369	        // `grouped` reason), so NO input could reach S4 and fail it — and its "can-fire"
370	        // re-typed the join as a hand-written `panic!` instead of exercising the gate's own
