1	//! PROBE-R2IL-REAL-EPISODES-1 — the frontier loop measured on REAL FunctionBehavior
2	//! episode streams (the named-not-built measurement from PROBE-R2IL-FRONTIER-PHASE2-1).
3	//!
4	//! # What the data is
5	//!
6	//! The ruff-side R2IL pass-1 harvest (`AdaWorldAPI/ruff`, `crates/ruff_r2il/examples/`
7	//! `harvest_r2il.rs`) lifted 143 real functions from real x86-64 ELF64 binaries
8	//! (`r2sleigh/tests/e2e/{stress_test,stress_test_opt}`; provenance FNV-pinned in ruff's
9	//! committed `.claude/harvest/r2il/PROVENANCE.md`) into 17,557 typed `FlatFact` rows —
10	//! one row per melted fact, smelt order, each carrying a 16-byte facet address. The bulk
11	//! artifact lives on the ruff GitHub Release `r2il-harvest-pass1`
12	//! (`r2il-pass1.ore.tsv.gz`); the census + slag + triage stay committed in ruff's tree.
13	//!
14	//! This probe READS that evidence file and measures. It is:
15	//! - **not a re-ingest path into ruff** (ruff's own rule "nothing in ruff parses them
16	//!   back" governs the ruff pipeline; a lance-graph-side probe measuring distributions
17	//!   from the evidence is a measurement, not a furnace input);
18	//! - **env-gated, never fabricating**: `R2IL_ORE_TSV` must point at the real TSV. If it
19	//!   is unset or missing, the probe prints the fetch instructions and exits with an
20	//!   explicit CORPUS ABSENT failure — it never synthesizes a stand-in corpus.
21	//!
22	//! ```sh
23	//! curl -sL https://github.com/AdaWorldAPI/ruff/releases/download/r2il-harvest-pass1/r2il-pass1.ore.tsv.gz \
24	//!   | zcat > /tmp/r2il-pass1.ore.tsv
25	//! R2IL_ORE_TSV=/tmp/r2il-pass1.ore.tsv \
26	//!   cargo run -p lance-graph-planner --example probe_r2il_real_episodes
27	//! ```
28	//!
29	//! # TSV schema (grounded in `ruff_r2il::furnace` module docs, ruff `origin/main`)
30	//!
31	//! `binary  function  fact_id  at  concern  kind  opcode  a  b  prov_inst  prov_block
32	//!  prov_op_site  prov_value` — payload per kind: `Op`: a = ordinal-in-block, b =
33	//! `input_arity | has_output << 32`; `OperandIn`: a = input index, b = `ValueId + 1`
34	//! (0 = no SSA value); `OperandOut`: a = 0, b = `ValueId + 1`.
35	//!
36	//! # Gates (each can fail; each failure would be a finding)
37	//!
38	//! - **E1 CONSERVATION** — recomputed census must equal ruff's independently committed
39	//!   `r2il-pass1-census.md` EXACTLY (5 fact kinds, 9 opcodes, total 17,557). This
40	//!   validates the reader against numbers this probe did not produce.
41	//! - **E2 EPISODES** — exactly 143 distinct functions across exactly 2 binaries (the
42	//!   README's measured count; the 2 stripped binaries never contributed functions).
43	//! - **E3 RECURRENCE** — real opcode-trigram structure vs a marginal-preserving
44	//!   within-function shuffle (deterministic LCG, fixed seed). The FIRST pre-registration
45	//!   ("real top-1 occurrence count > shuffled") was REFUTED on the real data (380 vs
46	//!   387) — top-1 count is maximized by the monotone (copy,copy,copy) runs the shuffle
47	//!   CREATES. The gate now asserts the measured structure: real streams collapse into
48	//!   >2x fewer distinct trigram types than shuffle, with higher top-10 occupancy, and
49	//!   the shuffle's top type is pinned to the predicted monotone-run artifact. The
50	//!   refutation is recorded in place, not adjusted away.
51	//! - **E4 FRONTIER ON REAL EPISODES** — the shipped loop (`TruthValue::revise` +
52	//!   `Stamp` disjointness, nothing new) run over real function-episodes as evidence
53	//!   events for the top recurring macros. Measures the e-values actually reached AND
54	//!   the modulo-64 stamp ceiling: with 143 episodes, `Stamp::source(i % 64)` collides,
55	//!   so evidence past 64 distinct sources is conservatively CHOICE-dropped — this gate
56	//!   measures how much.
57	//! - **E5 THE CLOBBER ANALOG ON REAL DATA (headline)** — sloppy admission = the opcode
58	//!   trigram matched. Contract admission = the occurrence is DATAFLOW-CHAINED (op i's
59	//!   `OperandOut` ValueId is consumed by an `OperandIn` of op i+1, twice). Measures the
60	//!   over-admission rate: the fraction of real opcode-gram occurrences a happy-path
61	//!   matcher would learn that are NOT dataflow-connected. Non-vacuity is enforced both
62	//!   ways (can-fire: some occurrence must fail the contract; can-stay-silent: some must
63	//!   pass) — if either side is empty on this corpus the gate fails as vacuous.
64	//!
65	//! # Fences (what this probe does NOT do)
66	//!
67	//! - No import of `ruff_r2il` (separate cargo workspace); the schema knowledge above is
68	//!   cited, and E1 exists precisely to catch a misread of it.
69	//! - No mint: no classid, no vocabulary table, no BPE, no learner subsystem. The
70	//!   R2IL × BPE / OGAR-loco / V4 synthesis stays a three-IF hypothesis.
71	//! - No performance claims. Counts and rates only.
72	
73	use std::collections::BTreeMap;
74	use std::process::ExitCode;
75	
76	use lance_graph_planner::nars::belief::Stamp;
77	use lance_graph_planner::nars::truth::TruthValue;
78	
79	// ================================================================================================
80	// TSV reading (probe-local; validated by E1 against the independently committed census)
81	// ================================================================================================
82	
83	#[derive(Clone)]
84	struct Row {
85	    binary: String,
86	    function: String,
87	    fact_id: u64,
88	    kind: String,
89	    opcode: String,
90	    b: u64,
91	    op_site: String,
92	}
93	
94	fn parse(tsv: &str) -> Vec<Row> {
95	    let mut rows = Vec::new();
96	    for line in tsv.lines() {
97	        if line.starts_with('#') || line.is_empty() {
98	            continue;
99	        }
100	        let f: Vec<&str> = line.split('\t').collect();
101	        assert!(
102	            f.len() == 13,
103	            "schema drift: expected 13 columns, got {}",
104	            f.len()
105	        );
106	        rows.push(Row {
107	            binary: f[0].to_string(),
108	            function: f[1].to_string(),
109	            fact_id: f[2].parse().expect("fact_id"),
110	            kind: f[5].to_string(),
111	            opcode: f[6].to_string(),
112	            b: f[8].parse().expect("b"),
113	            op_site: f[11].to_string(),
114	        });
115	    }
116	    rows
117	}
118	
119	/// One real function-episode: the smelt-ordered op sequence plus per-op-site dataflow.
120	struct Episode {
121	    /// Op sites in smelt (fact_id) order, each with its opcode.
122	    ops: Vec<(String, String)>, // (op_site, opcode)
123	    /// op_site -> ValueIds this op DEFINES (from OperandOut, b != 0 → ValueId = b-1).
124	    outs: BTreeMap<String, Vec<u64>>,
125	    /// op_site -> ValueIds this op CONSUMES (from OperandIn, b != 0).
126	    ins: BTreeMap<String, Vec<u64>>,
127	}
128	
129	fn episodes(rows: &[Row]) -> BTreeMap<(String, String), Episode> {
130	    let mut map: BTreeMap<(String, String), Episode> = BTreeMap::new();
131	    let mut op_order: BTreeMap<(String, String), Vec<(u64, String, String)>> = BTreeMap::new();
132	    for r in rows {
133	        let key = (r.binary.clone(), r.function.clone());
134	        let ep = map.entry(key.clone()).or_insert_with(|| Episode {
135	            ops: Vec::new(),
136	            outs: BTreeMap::new(),
137	            ins: BTreeMap::new(),
138	        });
139	        match r.kind.as_str() {
140	            "Op" => op_order.entry(key).or_default().push((
141	                r.fact_id,
142	                r.op_site.clone(),
143	                r.opcode.clone(),
144	            )),
145	            "OperandOut" if r.b != 0 => {
146	                ep.outs.entry(r.op_site.clone()).or_default().push(r.b - 1);
147	            }
148	            "OperandIn" if r.b != 0 => {
149	                ep.ins.entry(r.op_site.clone()).or_default().push(r.b - 1);
150	            }
151	            _ => {}
152	        }
153	    }
154	    for (key, mut ops) in op_order {
155	        ops.sort_by_key(|(fid, _, _)| *fid);
156	        map.get_mut(&key)
157	            .expect("episode exists for every op row")
158	            .ops = ops.into_iter().map(|(_, site, opc)| (site, opc)).collect();
159	    }
160	    map
161	}
162	
163	/// Deterministic LCG (fixed seed) — a reproducible within-function permutation for the
164	/// E3 marginal-preserving control. Numerical Recipes constants; not cryptographic.
165	struct Lcg(u64);
166	impl Lcg {
167	    fn next(&mut self) -> u64 {
168	        self.0 = self
169	            .0
170	            .wrapping_mul(6364136223846793005)
171	            .wrapping_add(1442695040888963407);
172	        self.0
173	    }
174	}
175	
176	fn shuffled(seq: &[String], lcg: &mut Lcg) -> Vec<String> {
177	    let mut s = seq.to_vec();
178	    for i in (1..s.len()).rev() {
179	        let j = (lcg.next() % (i as u64 + 1)) as usize;
180	        s.swap(i, j);
181	    }
182	    s
183	}
184	
185	fn trigram_counts(seqs: &[Vec<String>]) -> BTreeMap<(String, String, String), (usize, usize)> {
186	    // value = (total occurrences, distinct functions containing it)
187	    let mut counts: BTreeMap<(String, String, String), (usize, usize)> = BTreeMap::new();
188	    for seq in seqs {
189	        let mut seen_here: BTreeMap<(String, String, String), bool> = BTreeMap::new();
190	        for w in seq.windows(3) {
191	            let key = (w[0].clone(), w[1].clone(), w[2].clone());
192	            counts.entry(key.clone()).or_default().0 += 1;
193	            seen_here.entry(key).or_insert(true);
194	        }
195	        for (key, _) in seen_here {
196	            counts.entry(key).or_default().1 += 1;
197	        }
198	    }
199	    counts
200	}
