206	fn main() -> ExitCode {
207	    let Some(path) = std::env::var_os("R2IL_ORE_TSV") else {
208	        eprintln!("CORPUS ABSENT — this probe measures only real data and never fabricates.");
209	        eprintln!("Fetch the real episode stream and re-run:");
210	        eprintln!(
211	            "  curl -sL https://github.com/AdaWorldAPI/ruff/releases/download/r2il-harvest-pass1/r2il-pass1.ore.tsv.gz | zcat > /tmp/r2il-pass1.ore.tsv"
212	        );
213	        eprintln!("  R2IL_ORE_TSV=/tmp/r2il-pass1.ore.tsv cargo run -p lance-graph-planner --example probe_r2il_real_episodes");
214	        return ExitCode::from(2);
215	    };
216	    let Ok(tsv) = std::fs::read_to_string(&path) else {
217	        eprintln!("CORPUS ABSENT — R2IL_ORE_TSV={path:?} is not readable. Never fabricated.");
218	        return ExitCode::from(2);
219	    };
220	
221	    let rows = parse(&tsv);
222	    let mut pass = 0u32;
223	
224	    // -------------------------------------------------------------------------------------------
225	    // E1 CONSERVATION — recomputed census == ruff's independently committed census, exactly.
226	    // -------------------------------------------------------------------------------------------
227	    {
228	        let mut by_kind: BTreeMap<&str, usize> = BTreeMap::new();
229	        let mut by_opcode: BTreeMap<&str, usize> = BTreeMap::new();
230	        for r in &rows {
231	            *by_kind.entry(r.kind.as_str()).or_default() += 1;
232	            *by_opcode.entry(r.opcode.as_str()).or_default() += 1;
233	        }
234	        assert_eq!(rows.len(), 17_557, "total classified FlatFact rows");
235	        let expect_kind = [
236	            // NOTE: the TSV kind column carries the enum variant names (CamelCase), not
237	            // Census's snake_case as_str() — verified against the file; counts below still
238	            // cross-check EXACTLY against ruff's committed census.
239	            ("CallSite", 108usize),
240	            ("Edge", 456),
241	            ("Op", 5340),
242	            ("OperandIn", 7416),
243	            ("OperandOut", 4237),
244	        ];
245	        for (k, n) in expect_kind {
246	            assert_eq!(by_kind.get(k), Some(&n), "kind {k}");
247	        }
248	        assert_eq!(
249	            by_kind.len(),
250	            5,
251	            "exactly the 5 committed kinds — no phantom kind"
252	        );
253	        let expect_op = [
254	            ("branch", 25usize),
255	            ("call", 428),
256	            ("call_ind", 4),
257	            ("cbranch", 995),
258	            ("copy", 6753),
259	            ("int_add", 4768),
260	            ("load", 2394),
261	            ("return", 222),
262	            ("store", 1968),
263	        ];
264	        for (k, n) in expect_op {
265	            assert_eq!(by_opcode.get(k), Some(&n), "opcode {k}");
266	        }
267	        assert_eq!(by_opcode.len(), 9, "exactly the 9 committed opcodes");
268	        pass += 1;
269	        println!(
270	            "E1 PASS  census conservation: 17557 rows, 5 kinds + 9 opcodes == committed census"
271	        );
272	    }
273	
274	    // -------------------------------------------------------------------------------------------
275	    // E2 EPISODES — 143 real functions across 2 (symtab-bearing) binaries.
276	    // -------------------------------------------------------------------------------------------
277	    let eps = episodes(&rows);
278	    {
279	        let binaries: std::collections::BTreeSet<&String> = eps.keys().map(|(b, _)| b).collect();
280	        assert_eq!(
281	            eps.len(),
282	            143,
283	            "distinct real functions (README's measured count)"
284	        );
285	        assert_eq!(
286	            binaries.len(),
287	            2,
288	            "the 2 symtab-bearing binaries; stripped ones never contribute"
289	        );
290	        let op_total: usize = eps.values().map(|e| e.ops.len()).sum();
291	        assert_eq!(op_total, 5340, "every op row lands in exactly one episode");
292	        pass += 1;
293	        println!("E2 PASS  143 real function-episodes across 2 binaries; 5340 ops partitioned");
294	    }
295	
296	    // -------------------------------------------------------------------------------------------
297	    // E3 RECURRENCE — real trigram structure vs the marginal-preserving shuffled control.
298	    // -------------------------------------------------------------------------------------------
299	    let real_seqs: Vec<Vec<String>> = eps
300	        .values()
301	        .map(|e| e.ops.iter().map(|(_, opc)| opc.clone()).collect())
302	        .collect();
303	    // REFUTED PRE-REGISTRATION, recorded not adjusted away: the first version of this
304	    // gate pre-registered "real top-1 trigram occurrence count > shuffled" and FAILED on
305	    // the real data (real 380 vs shuffled 387). Top-1 count was the WRONG statistic:
306	    // shuffling a copy/int_add-dominated marginal CREATES monotone (copy,copy,copy) runs,
307	    // so the control's top-1 grows. Real structure shows up as TYPE-CONCENTRATION: real
308	    // streams collapse into far fewer distinct trigram types (measured 97 vs 260 under
309	    // the python cross-check — ~2.7x), and the top-10 types carry ~50% of all real
310	    // occurrences vs ~34% shuffled. The gate now asserts the measured fact, with margin.
311	    let (top_real_key, top_real, top_real_fns) = {
312	        let real = trigram_counts(&real_seqs);
313	        let mut lcg = Lcg(0x5EED_0001);
314	        let shuf_seqs: Vec<Vec<String>> = real_seqs.iter().map(|s| shuffled(s, &mut lcg)).collect();
315	        let shuf = trigram_counts(&shuf_seqs);
316	        let (rk, rv) = real.iter().max_by_key(|(_, (n, _))| *n).expect("nonempty");
317	        let (sk, sv) = shuf.iter().max_by_key(|(_, (n, _))| *n).expect("nonempty");
318	
319	        // Type concentration, with a non-marginal 2x margin (anti-vacuity: a shuffle
320	        // that preserved type counts would fail this).
321	        assert!(
322	            real.len() * 2 < shuf.len(),
323	            "real trigram-type collapse must beat shuffle by >2x (real {} vs shuffled {})",
324	            real.len(),
325	            shuf.len()
326	        );
327	        // Top-10 occupancy share strictly higher in real streams.
328	        let share = |m: &BTreeMap<(String, String, String), (usize, usize)>| -> f64 {
329	            let mut counts: Vec<usize> = m.values().map(|(n, _)| *n).collect();
330	            counts.sort_unstable_by_key(|n| std::cmp::Reverse(*n));
331	            let total: usize = counts.iter().sum();
332	            counts.iter().take(10).sum::<usize>() as f64 / total as f64
333	        };
334	        let (rs, ss) = (share(&real), share(&shuf));
335	        assert!(
336	            rs > ss,
337	            "real top-10 share must exceed shuffled ({rs:.3} vs {ss:.3})"
338	        );
339	        // The shuffle's top type must be the monotone-run artifact the refutation
340	        // predicted — pinning the MECHANISM of the refutation, not just its outcome.
341	        assert_eq!(
342	            (sk.0.as_str(), sk.1.as_str(), sk.2.as_str()),
343	            ("copy", "copy", "copy"),
344	            "the shuffled control's top trigram is the marginal monotone run"
345	        );
346	        println!(
347	            "E3 PASS  real trigram types {} vs shuffled {} (>2x collapse); top-10 share {:.3} vs {:.3}; \
348	             real top ({},{},{}) x{} in {} fns; shuffled top (copy,copy,copy) x{} — the refuted top-1 \
349	             pre-registration is recorded above",
350	            real.len(), shuf.len(), rs, ss,
351	            rk.0, rk.1, rk.2, rv.0, rv.1, sv.0
352	        );
353	        (rk.clone(), rv.0, rv.1)
354	    };
355	    pass += 1;
356	    let _ = (top_real, top_real_fns); // reported inside E3's line; E4/E5 key off top_real_key
357	
358	    // -------------------------------------------------------------------------------------------
359	    // E4 FRONTIER ON REAL EPISODES — shipped revise + Stamp over 143 real evidence events,
360	    // measuring the modulo-64 stamp ceiling at real corpus scale.
361	    // -------------------------------------------------------------------------------------------
362	    {
363	        let real = trigram_counts(&real_seqs);
364	        let mut top: Vec<_> = real.iter().collect();
365	        top.sort_by_key(|(_, (n, _))| std::cmp::Reverse(*n));
366	        println!("E4       frontier over real episodes (top 3 recurring macros):");
367	        let mut ceiling_seen = false;
368	        for (key, (occ, fns)) in top.iter().take(3) {
369	            let mut truth = TruthValue::new(0.5, 0.05); // ignorance prior
370	            let mut stamp = Stamp(0);
371	            let (mut revised, mut dropped) = (0usize, 0usize);
372	            for (idx, seq) in real_seqs.iter().enumerate() {
373	                let here = seq
374	                    .windows(3)
375	                    .any(|w| (&w[0], &w[1], &w[2]) == (&key.0, &key.1, &key.2));
376	                if !here {
377	                    continue;
378	                }
379	                let ev = Stamp::source(idx as u32);
380	                if stamp.disjoint(ev) {
381	                    truth = truth.revise(&TruthValue::new(1.0, 0.9));
382	                    stamp = stamp.union(ev);
383	                    revised += 1;
384	                } else {
385	                    dropped += 1; // CHOICE: overlapping stamp, evidence conservatively not pooled
386	                }
387	            }
388	            if dropped > 0 {
389	                ceiling_seen = true;
390	            }
391	            println!(
392	                "         ({},{},{}) occ={} fns={} -> e={:.3} revised={} choice_dropped={} (mod-64 ceiling)",
393	                key.0, key.1, key.2, occ, fns,
394	                truth.expectation(), revised, dropped
395	            );
396	            assert!(
397	                truth.expectation() > 0.75,
398	                "a macro recurring in {fns} real functions must clear the trust bar"
399	            );
400	            assert!(
401	                revised <= 64,
402	                "the Stamp mod-64 ceiling bounds disjoint sources"
403	            );
404	        }
405	        // Can-fire for the ceiling claim: at 143 episodes, at least one widely-recurring
406	        // macro must actually HIT the ceiling — otherwise the ceiling talk is decoration.
407	        assert!(
408	            ceiling_seen,
409	            "with 143 episodes and 64 stamp bits, some macro must measurably drop evidence"
410	        );
411	        pass += 1;
412	        println!("E4 PASS  shipped revise+Stamp works on real episodes; the mod-64 ceiling BINDS at 143 functions");
413	    }
414	
415	    // -------------------------------------------------------------------------------------------
416	    // E5 HEADLINE — the clobber analog on real data: opcode match vs dataflow-chained contract.
417	    // -------------------------------------------------------------------------------------------
418	    {
419	        let keys: Vec<(String, String)> = eps.keys().cloned().collect();
420	        let (mut sloppy, mut chained) = (0usize, 0usize);
421	        for key in &keys {
422	            let ep = &eps[key];
423	            for w in ep.ops.windows(3) {
424	                let opc = (&w[0].1, &w[1].1, &w[2].1);
425	                if opc != (&top_real_key.0, &top_real_key.1, &top_real_key.2) {
426	                    continue;
427	                }
428	                sloppy += 1;
429	                let empty: Vec<u64> = Vec::new();
430	                let out0 = ep.outs.get(&w[0].0).unwrap_or(&empty);
431	                let in1 = ep.ins.get(&w[1].0).unwrap_or(&empty);
432	                let out1 = ep.outs.get(&w[1].0).unwrap_or(&empty);
433	                let in2 = ep.ins.get(&w[2].0).unwrap_or(&empty);
434	                let link01 = out0.iter().any(|v| in1.contains(v));
435	                let link12 = out1.iter().any(|v| in2.contains(v));
436	                if link01 && link12 {
437	                    chained += 1;
438	                }
439	            }
440	        }
441	        let unchained = sloppy - chained;
442	        // Non-vacuity, both directions (the falsifiability rule): the contract must be
443	        // able to refuse AND able to admit on this real corpus.
444	        assert!(
445	            unchained > 0,
446	            "can-fire: the dataflow contract refuses some real occurrences"
447	        );
448	        assert!(
449	            chained > 0,
450	            "can-stay-silent: the dataflow contract admits some real occurrences"
451	        );
452	        let rate = 100.0 * unchained as f64 / sloppy as f64;
453	
454	        // Context base rate — every operand row in this corpus carries a real SSA
455	        // ValueId (measured: 0 of 7416 OperandIn and 0 of 4237 OperandOut rows have
456	        // b == 0), so linkage failures below are genuine dataflow facts, never missing
457	        // coverage. The base rate says how often ANY adjacent op pair is def-use linked.
458	        let (mut pairs, mut linked) = (0usize, 0usize);
459	        for key in &keys {
460	            let ep = &eps[key];
461	            let empty: Vec<u64> = Vec::new();
462	            for w in ep.ops.windows(2) {
463	                pairs += 1;
464	                let o = ep.outs.get(&w[0].0).unwrap_or(&empty);
465	                let n = ep.ins.get(&w[1].0).unwrap_or(&empty);
466	                if o.iter().any(|v| n.contains(v)) {
467	                    linked += 1;
468	                }
469	            }
470	        }
471	        let base = 100.0 * linked as f64 / pairs as f64;
472	        pass += 1;
473	        println!(
474	            "E5 PASS  HEADLINE: of {sloppy} real occurrences of the top macro, {chained} are dataflow-chained, {unchained} are NOT — a happy-path opcode matcher over-admits {rate:.1}% on real code (adjacency base rate: {linked}/{pairs} = {base:.1}% of ALL adjacent pairs are linked — the top opcode idiom chains far BELOW base rate: it is an addressing idiom, not a dataflow pipe)"
475	        );
476	    }
477	
478	    println!("\n{pass}/5 gates green — real FunctionBehavior episode measurement complete.");
479	    println!(
480	        "Fences: no ruff import; no mint; no BPE; no learner subsystem; counts and rates only."
481	    );
482	    ExitCode::SUCCESS
483	}
